class Solution {
    private int n;
    private int dfs(int[][] grid, int r, int c, int tag) {
        grid[r][c] = tag;
        int cnt = 1;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                cnt += dfs(grid, nr, nc, tag);
            }
        }
        return cnt;
    }
    public int largestIsland(int[][] grid) {
        n = grid.length;
        Map<Integer, Integer> area = new HashMap<>();
        int tag = 2;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    area.put(tag, dfs(grid, r, c, tag));
                    tag++;
                }
            }
        }
        int ans = 0;
        for (int a : area.values()) ans = Math.max(ans, a);
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    Set<Integer> seen = new HashSet<>();
                    for (int[] d : dirs) {
                        int nr = r + d[0], nc = c + d[1];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] > 1) {
                            seen.add(grid[nr][nc]);
                        }
                    }
                    int cand = 1;
                    for (int t : seen) cand += area.get(t);
                    ans = Math.max(ans, cand);
                }
            }
        }
        return ans;
    }
}

